entries[130325] = { ["name"] = "Lied der Harmonie", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nWindwollstoffballen (5), Geist der Harmonie (3)\nDiese Spezialmethode zur Herstellung kaiserlicher Seide kann so oft eingesetzt werden, wie es dem Schneider beliebt. Vorausgesetzt, es stehen die benötigten Materialien zur Verfügung.\nBeruf:\nSchneiderei von Pandaria (35)\nLehrer:\nSeidenmeister Tsai\nZone:\nTal der Vier Winde\nKosten:\n1\n30\n\nKaiserliche Seide\nWird beim Aufheben gebunden\nHandwerksmaterial" }
entries[130326] = { ["name"] = "Stahlherstellung", ["text"] = "Wirken in 1.5 sek.\nTools: Stein der Weisen\nReagenzien:\nTrilliumbarren (3), Geist der Harmonie (3)\nBeim Durchführen dieser Transmutation besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\nDie Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\nGeister der Harmonie zu verwenden, um lebendigen Stahl herzustellen, erschöpft den Alchemisten nicht, wodurch er den Ruhetag ignorieren kann, der bei anderen Transmutationen nötig ist.\nBeruf:\nAlchemie von Pandaria\nEntdeckung:\nWeitere Alchemierezepte aus Pandaria\n\nLebendiger Stahl\nHandwerksmaterial" }
